import{_ as d,C as s,o as u,c as m,j as t,a,E as o,a8 as g}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/IavxrdVnwXM-640.webp",b="/schedule-dashboard/thumbs/yt/IavxrdVnwXM-1280.webp",n="/schedule-dashboard/thumbs/yt/SHMCGrNJJGc-640.webp",v="/schedule-dashboard/thumbs/yt/SHMCGrNJJGc-1280.webp",i="/schedule-dashboard/thumbs/yt/e9-br9hveRI-640.webp",f="/schedule-dashboard/thumbs/yt/e9-br9hveRI-1280.webp",l="/schedule-dashboard/thumbs/yt/Ti-BmGU1_mQ-640.webp",y="/schedule-dashboard/thumbs/yt/Ti-BmGU1_mQ-1280.webp",h="/schedule-dashboard/thumbs/yt/KtBivPzmOM8-640.webp",k="/schedule-dashboard/thumbs/yt/KtBivPzmOM8-1280.webp",c="/schedule-dashboard/thumbs/yt/NXCFYzRfQIk-640.webp",_="/schedule-dashboard/thumbs/yt/NXCFYzRfQIk-1280.webp",H=JSON.parse('{"title":"AI Digest · Sun 18 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-18","routine":"digest"},"relativePath":"digest/2026-10-18.md","filePath":"digest/[date].md"}'),I={name:"digest/2026-10-18.md"},M=r+" 640w, "+b+" 1280w",A=n+" 640w, "+v+" 1280w",G=i+" 640w, "+f+" 1280w",C=l+" 640w, "+y+" 1280w",x=h+" 640w, "+k+" 1280w",S=c+" 640w, "+_+" 1280w",T={id:"ai-digest-·-sun-18-oct-2026",tabindex:"-1"};function N(z,e,J,B,R,O){const p=s("Badge"),w=s("DayFilter");return u(),m("div",null,[t("h1",T,[e[0]||(e[0]=a("AI Digest · Sun 18 Oct 2026 ",-1)),o(p,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sun-18-oct-2026","aria-label":'Permalink to "AI Digest · Sun 18 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (18 Oct 2026) · run date Sun 18 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(` posted 5 videos (about 6.3 hours, mostly long workshops). The freshest is a 43-minute Keycard, JPMorgan Chase and AAuth panel on intent-based authorization for agents, built around the agent that got its user banned from Resy. The standout is Laurie Voss's Arize Phoenix evals workshop, where an agent's "116% of analysts agree" bug drives a full trace, judge, experiment and CI loop. Eugene Cheah's tokenomics talk is dense with real cost numbers, and Monzo's trust-principles workshop is useful but slow. Oracle's AML harness workshop is mostly repeat ground (harnesses, agent memory, context engineering, skills).`)]),t("p",null,[t("strong",null,"Better Stack"),a(" posted 1 video: a 6-minute explainer on DNSSEC and the 11 October root key rollover that knocked some routers offline. It isn't a repeat; DNS hasn't come up before.")])],-1)),o(w),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-IavxrdVnwXM" data-title="An AI Agent Got Its User Banned From Resy — Keycard, JPMorgan Chase &amp; AAuth" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=IavxrdVnwXM" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=IavxrdVnwXM" target="_blank" rel="noopener">An AI Agent Got Its User Banned From Resy — Keycard, JPMorgan Chase &amp; AAuth</a></h3><div class="meta">AI Engineer · Allie Howe (Keycard, moderator), Ian Livingstone (Keycard CEO), Michael Davis (JPMorgan Chase), Dick Hardt (AAuth, OAuth co-creator) · uploaded 18 Oct, 4:30 AM IST · 43:25</div><div class="verdict v-skim"><b>Verdict:</b> skim from (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=420s" target="_blank" rel="noopener">7:00</a>): the mission, Resy-budget and brain-vs-hands sections are the substance; the rest is panel generalities.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 18 times before. New here: intent-based runtime authorization, and AAuth&#39;s &quot;mission&quot; and &quot;budget&quot; primitives as a protocol rather than a vendor feature.</div><div class="repeat">🔁 Repeat: &#39;agent governance&#39; — seen 6 times before. New here: a bank security architect&#39;s view on &quot;know your agent&quot; alongside know-your-customer.</div><div class="sh">Why OAuth doesn&#39;t fit agents</div><ul><li><strong>Security systems built for humans:</strong> Enterprises, especially regulated ones, put security first, and their identity stacks were designed for humans making decisions and deterministic software, not a model that retries until it finds a way (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Scopes are too coarse:</strong> You don&#39;t know in advance what an agent will need, so mapping existing OAuth scopes onto agents is far too coarse; for example, Notion&#39;s MCP server lets you fetch a page but not just one database on that page (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Intent as the memo field:</strong> One panelist compares intent to the memo line on a cheque: the cheque still has hard limits (amount, payee, date), but the memo explains the purpose, which makes runtime decisions and debugging easier (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">Missions, budgets and the Resy incident</div><ul><li><strong>AAuth missions:</strong> A mission is the big-picture goal the agent works toward on behalf of a person or organization; every decision is made in its context and the mission ID tracks through everything for auditing (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li><li><strong>A separate supervisor:</strong> The AAuth view is a supervising agent that can&#39;t do any work itself but decides what the worker agent is allowed to do (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li><li><strong>The Resy ban:</strong> An agent trying to book a restaurant made 200 API calls an hour and got the user&#39;s Resy account banned; AAuth answers this with budgets, so a token expires either on time or when its resource budget runs out (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1500s" target="_blank" rel="noopener">25:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1620s" target="_blank" rel="noopener">27:00</a>)</li><li><strong>Brain vs hands:</strong> Keep credentials and enforcement in a deterministic layer outside the model, the pattern Anthropic and OpenAI are following, and remove tools dynamically, e.g. disable web egress while an email-writing step is in progress (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1680s" target="_blank" rel="noopener">28:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1860s" target="_blank" rel="noopener">31:00</a>)</li></ul><div class="sh">Production reality and P(doom)</div><ul><li><strong>Intent saves tokens too:</strong> Telling the agent what it shouldn&#39;t do nudges it onto a paved path, so it wastes fewer tokens or stops and says it can&#39;t do the task (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1860s" target="_blank" rel="noopener">31:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=1920s" target="_blank" rel="noopener">32:00</a>)</li><li><strong>Lessons from robotics:</strong> Most authorization today is a single binary decision; Davis wants context-rich, short-lived decisions that also weigh environment signals like location, time of day or which browser an admin is using (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2100s" target="_blank" rel="noopener">35:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2280s" target="_blank" rel="noopener">38:00</a>)</li><li><strong>Audit log outside the agent:</strong> You still need a record of who told the agent to do what and for what purpose, kept outside the agent itself (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2280s" target="_blank" rel="noopener">38:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2340s" target="_blank" rel="noopener">39:00</a>)</li><li><strong>P(doom):</strong> One panelist worries most about insider threats and irresponsible actors causing disaster-scale harm; another puts the odds at &quot;approaching asymptotically zero&quot; because incentives and liability frameworks still apply (<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2340s" target="_blank" rel="noopener">39:00</a>–<a href="https://www.youtube.com/watch?v=IavxrdVnwXM&amp;t=2600s" target="_blank" rel="noopener">43:20</a>)</li></ul></div></article><article class="it full" id="v-SHMCGrNJJGc" data-title="How to Know If Your AI Agent Is Any Good: Evals With Phoenix &amp; Claude — Laurie Voss, Arize AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=SHMCGrNJJGc" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=SHMCGrNJJGc" target="_blank" rel="noopener">How to Know If Your AI Agent Is Any Good: Evals With Phoenix &amp; Claude — Laurie Voss, Arize AI</a></h3><div class="meta">AI Engineer · Laurie Voss (Head of DevRel, Arize AI; npm co-founder) · uploaded 18 Oct, 12:30 AM IST · 1:56:13</div><div class="verdict v-worth"><b>Verdict:</b> worth watching, or skim from (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=2601s" target="_blank" rel="noopener">43:21</a>) if you already trace your agents: the judge-validation and experiment sections are the best evals material in a while.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 29 times before. New here: a full worked loop on one agent with real numbers, including testing the judge itself against human labels and proving a model upgrade with evidence.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 17 times before. Tracing setup with Phoenix is standard; the error-analysis-by-coding-agent part is the fresher bit.</div><div class="sh">The mental model</div><ul><li><strong>Traces are logs, evals are tests:</strong> Evals are tests run on traces for outputs that are never the same twice; &quot;looks good to me&quot; on three tries isn&#39;t a test suite and doesn&#39;t catch regressions (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=297s" target="_blank" rel="noopener">4:57</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>Three kinds of eval:</strong> Code evals are instant and free (formats, required fields, banned phrases), LLM judges handle meaning but can be confidently wrong, and humans catch unknown failures and check the judges (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=510s" target="_blank" rel="noopener">8:30</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=717s" target="_blank" rel="noopener">11:57</a>)</li><li><strong>Agents fail in cascades:</strong> A financial agent asked about Tesla can find the 18th-century inventor and write a perfectly formatted, wrong report; in one airline benchmark Claude upgraded a passenger to first class to change seats, then downgraded them back (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=717s" target="_blank" rel="noopener">11:57</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=840s" target="_blank" rel="noopener">14:00</a>)</li></ul><div class="sh">Reading traces: the 116% bug</div><ul><li><strong>Setup:</strong> A Claude Agent SDK financial analyst on Claude Haiku 4.5 with a research turn and a writing turn, traced with Phoenix in about five lines of TypeScript (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=992s" target="_blank" rel="noopener">16:32</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=1320s" target="_blank" rel="noopener">22:00</a>)</li><li><strong>The bug:</strong> For &quot;yo is Tesla a buy right now&quot;, it merged two unrelated web results into 50% buy, 52.6% hold and 13.1% sell, about 116% of analysts, and stated it confidently (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=2601s" target="_blank" rel="noopener">43:21</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=2700s" target="_blank" rel="noopener">45:00</a>)</li><li><strong>Other failures found:</strong> An ambiguous prompt plus no-permission mode made it keep trying to write the report to a file, and many reports never said buy, sell or hold (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=1680s" target="_blank" rel="noopener">28:00</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=1860s" target="_blank" rel="noopener">31:00</a>)</li></ul><div class="sh">Writing evals</div><ul><li><strong>Code eval first:</strong> A ticker-mention check runs instantly and caught the Amazon query where the agent wrote only about AWS (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=3036s" target="_blank" rel="noopener">50:36</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=3300s" target="_blank" rel="noopener">55:00</a>)</li><li><strong>Correctness eval failed everything:</strong> Phoenix&#39;s built-in correctness judge (on Sonnet 5.5) marked every report wrong because October stock prices are after Claude&#39;s knowledge cutoff; faithfulness against the search results was the right choice and flagged 14 of 16 reports with useful explanations (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=3630s" target="_blank" rel="noopener">1:00:30</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=4020s" target="_blank" rel="noopener">1:07:00</a>)</li><li><strong>Custom actionability judge:</strong> A five-part rubric whose criteria come from your own error analysis; 5 of 16 reports passed, and simply wrapping inputs in XML tags flipped results, so treat eval prompts as code (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=4241s" target="_blank" rel="noopener">1:10:41</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=5040s" target="_blank" rel="noopener">1:24:00</a>)</li></ul><div class="sh">Trusting the judge and shipping</div><ul><li><strong>Test the judge:</strong> Label reports yourself, split 75/25 into dev and test, and measure the judge&#39;s precision and recall like a classifier; humans disagree too, so the bar is &quot;better than another human&quot; (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=5085s" target="_blank" rel="noopener">1:24:45</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=5880s" target="_blank" rel="noopener">1:38:00</a>)</li><li><strong>Experiments prove fixes:</strong> One prompt line raised actionability from 5/16 to 48/48 across three runs, but faithfulness only went from 2/16 to 3/48, so the agent still invents numbers (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=5935s" target="_blank" rel="noopener">1:38:55</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=6420s" target="_blank" rel="noopener">1:47:00</a>)</li><li><strong>Haiku 5.5 upgrade:</strong> Faithfulness more than tripled but stayed poor, cost rose about 4×, and it got &quot;consistent&quot; by answering hold 41 of 45 times (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=6510s" target="_blank" rel="noopener">1:48:30</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=6655s" target="_blank" rel="noopener">1:50:55</a>)</li><li><strong>Evals in CI:</strong> `npm test` gates on the ticker check as a guardrail and average actionability of 0.8 or better as a target (<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=6655s" target="_blank" rel="noopener">1:50:55</a>–<a href="https://www.youtube.com/watch?v=SHMCGrNJJGc&amp;t=6925s" target="_blank" rel="noopener">1:55:25</a>)</li></ul></div></article><article class="it full" id="v-e9-br9hveRI" data-title="Stop Chatting With Spreadsheets — Francesco Galletta &amp; Felippe Felisola Caso, Monzo" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=e9-br9hveRI" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+G+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=e9-br9hveRI" target="_blank" rel="noopener">Stop Chatting With Spreadsheets — Francesco Galletta &amp; Felippe Felisola Caso, Monzo</a></h3><div class="meta">AI Engineer · Francesco Galletta &amp; Felippe Felisola Caso (Monzo, speaking for themselves) · uploaded 17 Oct, 7:30 PM IST · 1:50:34</div><div class="verdict v-skim"><b>Verdict:</b> skim from (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=2148s" target="_blank" rel="noopener">35:48</a>): the branching-plan and math-in-code sections plus the evidence labels are the takeaways; much of the runtime is live setup and audience back-and-forth.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 20 times before. New here: five trust principles applied to a finance harness, with a branching plan instead of one linear chat.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 8 times before. New here: &quot;few gates with very high signal&quot;, reviewing tasks rather than individual changes.</div><div class="sh">Trust, not speed</div><ul><li><strong>Impact over token-maxing:</strong> Their Monzo team adopts AI deliberately for concrete business value, not to spend tokens (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=174s" target="_blank" rel="noopener">2:54</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=262s" target="_blank" rel="noopener">4:22</a>)</li><li><strong>The five principles:</strong> Shared domain, consistency, evidence, accountability and verification, each building on the last (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=525s" target="_blank" rel="noopener">8:45</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=733s" target="_blank" rel="noopener">12:13</a>)</li><li><strong>The use case:</strong> Paying for a wedding in three payments with fixed costs (DJ, flowers) and an unknown guest count at about 150 per seat; the harness keeps asking questions instead of going &quot;yes-man&quot; (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=1559s" target="_blank" rel="noopener">25:59</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=1842s" target="_blank" rel="noopener">30:42</a>)</li></ul><div class="sh">Consistency and evidence</div><ul><li><strong>Branches, not one long chat:</strong> The plan becomes a decision tree you can edit node by node, because long linear chats fall apart when one stray sentence derails the analysis (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=2148s" target="_blank" rel="noopener">35:48</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=2208s" target="_blank" rel="noopener">36:48</a>)</li><li><strong>Math belongs in code:</strong> Deterministic pieces become tested code and versioned libraries the agent calls, not arithmetic &quot;in the model&#39;s head&quot; that gets reinvented every session (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=2208s" target="_blank" rel="noopener">36:48</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=2700s" target="_blank" rel="noopener">45:00</a>)</li><li><strong>Label every input:</strong> Chat thoughts are interpretations, agent memory is an assumption, a bank statement is a fact; the &quot;master file&quot; story shows how hidden assumptions break analyses (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=3540s" target="_blank" rel="noopener">59:00</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=3660s" target="_blank" rel="noopener">1:01:00</a>)</li></ul><div class="sh">Accountability and verification</div><ul><li><strong>Agents face no consequences, you do:</strong> Design a few high-signal gates for real judgment calls rather than approving every change (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=4002s" target="_blank" rel="noopener">1:06:42</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=4320s" target="_blank" rel="noopener">1:12:00</a>)</li><li><strong>Challenge branches:</strong> A separate reviewer agent challenges the plan and its result merges back in, or you dismiss it; golden examples alone carry your own selection bias, so add outside reference points (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=5040s" target="_blank" rel="noopener">1:24:00</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=5520s" target="_blank" rel="noopener">1:32:00</a>)</li><li><strong>Harness vs skills (Q&amp;A):</strong> Skills work about 99% of the time, but a user-level CLAUDE.md can contradict them; build a dedicated harness when reproducibility matters, and don&#39;t over-sharpen the axe (<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=5891s" target="_blank" rel="noopener">1:38:11</a>–<a href="https://www.youtube.com/watch?v=e9-br9hveRI&amp;t=6400s" target="_blank" rel="noopener">1:46:40</a>)</li></ul></div></article><article class="it full" id="v-Ti-BmGU1_mQ" data-title="The AI Bill Is Too Damn High: Tokenomics 101 — Eugene Cheah, Featherless AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ" target="_blank" rel="noopener">The AI Bill Is Too Damn High: Tokenomics 101 — Eugene Cheah, Featherless AI</a></h3><div class="meta">AI Engineer · Eugene Cheah (CEO, Featherless AI) · uploaded 17 Oct, 2:30 PM IST · 55:25</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you pay a token bill; Moves 2 to 4 <a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=567s" target="_blank" rel="noopener">9:27</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=2667s" target="_blank" rel="noopener">44:27</a> are the dense part.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 40 times before. New here: concrete right-sizing numbers from an inference vendor serving customers up to 2 trillion tokens a day.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 28 times before. New here: the &quot;2× speed costs 3× the money&quot; rule with real throughput figures.</div><div class="repeat">🔁 Repeat: &#39;AI ROI measurement&#39; — seen 4 times before. New here: &quot;tokens are not work done&quot; and the slop-grenade anti-pattern.</div><div class="sh">Move 1: measure</div><ul><li><strong>Stop sharing one API key:</strong> Split keys by department and use case so you can see who spends what; he calls measuring the biggest ROI step (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=203s" target="_blank" rel="noopener">3:23</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Two opposite workloads:</strong> Agentic work (one team of 5 devs averaged 8 agents running continuously) vs high-volume process work like content filtering and OCR; that team moved background agents to run overnight (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=312s" target="_blank" rel="noopener">5:12</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=567s" target="_blank" rel="noopener">9:27</a>)</li></ul><div class="sh">Move 2: right-size models</div><ul><li><strong>Open models catch up:</strong> Kimi K3 beat Opus on public UI-design benchmarks before Opus 5.5, and DeepSeek-V4 Flash is popular across workloads; classifiers are about 10× cheaper where you don&#39;t need a chat reply (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li><li><strong>Plan big, build cheap:</strong> Use a frontier model to plan and review and a cheap one like Gemini 5.3 Flash for workers; teams with loose budgets never switch models, teams with tiny ones abandon the smart model entirely (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=900s" target="_blank" rel="noopener">15:00</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=1080s" target="_blank" rel="noopener">18:00</a>)</li><li><strong>Model labels, not names:</strong> Give departments labels you control (one team was still running Llama 2 models); a telco went from 250k to 7.6k a month, and AT&amp;T fine-tuned down to 27B and 7B models (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=1167s" target="_blank" rel="noopener">19:27</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=1500s" target="_blank" rel="noopener">25:00</a>)</li></ul><div class="sh">Moves 3 and 4: buy capacity, fix process</div><ul><li><strong>Speed is expensive:</strong> Every 2× in speed costs about 3×; one server did 112 tokens/s on a single request, while 16 parallel requests ran at about half the speed for about 10× the total throughput, so don&#39;t run background jobs at 120 tokens/s (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=1807s" target="_blank" rel="noopener">30:07</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=1942s" target="_blank" rel="noopener">32:22</a>)</li><li><strong>Tokens are not work done:</strong> Reports show only 6–7% productivity gains; spamming agents creates duplicate work and review bottlenecks, and &quot;slop grenades&quot; dump AI output on others, so people must own what they hand over (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=2072s" target="_blank" rel="noopener">34:32</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=2667s" target="_blank" rel="noopener">44:27</a>)</li><li><strong>Q&amp;A:</strong> A prompt-tuned Qwen 27B beat most 27B fine-tunes on a benchmark, golden traces get heavier weight in SFT, and turn-based auto-routing should stick to 2–3 models or caching breaks (<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=2667s" target="_blank" rel="noopener">44:27</a>–<a href="https://www.youtube.com/watch?v=Ti-BmGU1_mQ&amp;t=3300s" target="_blank" rel="noopener">55:00</a>)</li></ul></div></article><article class="it full" id="v-KtBivPzmOM8" data-title="Memory-Aware Agent Harnesses for Anti-Money Laundering — Nacho Martinez, Oracle" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=KtBivPzmOM8" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=KtBivPzmOM8" target="_blank" rel="noopener">Memory-Aware Agent Harnesses for Anti-Money Laundering — Nacho Martinez, Oracle</a></h3><div class="meta">AI Engineer · Nacho Martinez (AI developer advocate, Oracle) · uploaded 17 Oct, 12:30 PM IST · 51:49</div><div class="verdict v-skim"><b>Verdict:</b> skim from (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=801s" target="_blank" rel="noopener">13:21</a>) to about (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1600s" target="_blank" rel="noopener">26:40</a>) for the files-vs-databases and skillbox ideas; the rest is well-covered harness/memory ground plus workshop setup.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 20 times before. Mostly the same &quot;harness matters more than the model&quot; argument.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 14 times before. Summarization vs compaction and context rot are familiar.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 13 times before. The short-term vs episodic/procedural/semantic split is familiar.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 7 times before. New here: vector-retrieving skills and tools (a &quot;skillbox&quot;) instead of loading them all.</div><div class="sh">The stack (repeat-heavy)</div><ul><li><strong>Use case:</strong> An always-on agent for a mid-sized bank that flags suspicious transactions, like $1M deposited and then $50,000 ATM withdrawals for three days, and writes findings for a human to review (repeat) (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=297s" target="_blank" rel="noopener">4:57</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=357s" target="_blank" rel="noopener">5:57</a>)</li><li><strong>Harness over model:</strong> You can&#39;t change the frontier model, but changing the harness alone makes the same model better or worse (repeat) (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=666s" target="_blank" rel="noopener">11:06</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=801s" target="_blank" rel="noopener">13:21</a>)</li><li><strong>Files vs databases:</strong> Worktrees are a workaround for multiple agents writing the same files; ACID databases solved that 30 years ago (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=801s" target="_blank" rel="noopener">13:21</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=956s" target="_blank" rel="noopener">15:56</a>)</li><li><strong>Context rot:</strong> Models solve problems more accurately at zero tokens than with 256K already in context, even with 1M limits (repeat) (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1080s" target="_blank" rel="noopener">18:00</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1186s" target="_blank" rel="noopener">19:46</a>)</li></ul><div class="sh">Toolbox, skillbox and continual learning</div><ul><li><strong>Vectorize skills and tools:</strong> With about 100 skills at 3,000–5,000 tokens each, tools and skills can be over half the context; embed them and retrieve the top 3 per request (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1251s" target="_blank" rel="noopener">20:51</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1350s" target="_blank" rel="noopener">22:30</a>)</li><li><strong>Skill distillation:</strong> Turn successful past runs into reusable skills the agent finds by semantic search, so a frozen model improves through its data layer (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1350s" target="_blank" rel="noopener">22:30</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=1570s" target="_blank" rel="noopener">26:10</a>)</li><li><strong>Lean harness:</strong> His harness starts at about 6,000 tokens per request vs 30,000–40,000 for others, and a semantic cache cuts costs 4–5× (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=2160s" target="_blank" rel="noopener">36:00</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=2340s" target="_blank" rel="noopener">39:00</a>)</li></ul><div class="sh">Q&amp;A</div><ul><li><strong>Keep memory simple:</strong> Start with just short-term and long-term and promote what&#39;s worth keeping; use MCP for pre-built, proven SQL queries rather than dynamic ones, and hybrid search (embeddings plus keyword, RRF) for retrieval (<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=2449s" target="_blank" rel="noopener">40:49</a>–<a href="https://www.youtube.com/watch?v=KtBivPzmOM8&amp;t=2859s" target="_blank" rel="noopener">47:39</a>)</li></ul></div></article><article class="it full" id="v-NXCFYzRfQIk" data-title="The Internets Master Key Just Changed" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=NXCFYzRfQIk" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=NXCFYzRfQIk" target="_blank" rel="noopener">The Internets Master Key Just Changed</a></h3><div class="meta">Better Stack · uploaded 17 Oct, 11:30 AM IST · 5:55</div><div class="verdict v-worth"><b>Verdict:</b> worth watching: a short, concrete explainer, and practical if anything at home stopped resolving last week.</div><div class="sh">How DNS gets faked</div><ul><li><strong>No proof in original DNS:</strong> A resolver tags each query with a random ID and accepts any answer with a matching ID; there are only about 65,000 IDs, so an attacker flooding fake answers needs about 32,000 guesses on average to poison the cache (<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=56s" target="_blank" rel="noopener">0:56</a>–<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=131s" target="_blank" rel="noopener">2:11</a>)</li><li><strong>2008 and DNSSEC:</strong> A researcher chained these weaknesses in 2008 and DNS software everywhere was patched; the long-term fix, DNSSEC (written in 2005), signs each step of the root to .com to example.com chain (<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=131s" target="_blank" rel="noopener">2:11</a>–<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=186s" target="_blank" rel="noopener">3:06</a>)</li></ul><div class="sh">The root key and the rollover</div><ul><li><strong>The key nobody can know:</strong> The root&#39;s secret key only signs the root&#39;s own key list and leaves the vault a few times a year; on 11 October the root switched from the 2017 key to the 2024 one (key 38696) (<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=160s" target="_blank" rel="noopener">2:40</a>–<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=218s" target="_blank" rel="noopener">3:38</a>)</li><li><strong>Inside Culpeper:</strong> The key sits seven layers deep in a Virginia facility; the machine needs 3 of 7 crypto officers&#39; USB keys (from places like Sweden, Zimbabwe, Chile and Sri Lanka, none working for ICANN), and the 2024 key was generated live on 26 April 2024 in about half a second (<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=218s" target="_blank" rel="noopener">3:38</a>–<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=315s" target="_blank" rel="noopener">5:15</a>)</li></ul><div class="sh">Who is protected</div><ul><li><strong>Low adoption, easy fix:</strong> Only about 5% of .com names are signed and about 41% of users sit behind a validating resolver; if your internet broke around 11 October, update your router or system so it picks up the new key (<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=315s" target="_blank" rel="noopener">5:15</a>–<a href="https://www.youtube.com/watch?v=NXCFYzRfQIk&amp;t=354s" target="_blank" rel="noopener">5:54</a>)</li></ul></div></article></div>',1))])}const V=d(I,[["render",N]]);export{H as __pageData,V as default};
